-- 4. Remove Jul-Dec rest days that no longer match the schedule (not Sunday, not their weekday_off).
DELETE d FROM `day_offs` d JOIN `employees` e ON e.id = d.employee_id
WHERE e.emp_code IN ('44', '4', '51', '11', '9', '14', '8', '7', '13', '68', '24', '52', '32', '45', '48', '47', '5', '16', '72', '23', '49', '46', '18', '19', '20', '12', '15', '10', '17', '21', '22', '43', '25', '62')
  AND d.type = 'rest_day' AND d.date BETWEEN '2026-07-01' AND '2026-12-31'
  AND (DAYOFWEEK(d.date) - 1) NOT IN (0, e.weekday_off);

-- 5. Sunday rest + weekly rest day, Jul 1 - Dec 31 2026. Existing rows are kept (unique employee_id+date).
