INSERT IGNORE INTO `day_offs` (`employee_id`, `date`, `type`, `description`, `is_recurring`, `recurring_day_of_week`, `created_by`, `created_at`, `updated_at`)
SELECT e.id, t.d, 'rest_day', IF(t.dow = 0, 'Sunday rest', 'Weekly rest day'), 1, t.dow,
       (SELECT id FROM `users` WHERE `role` = 'hr_admin' ORDER BY id LIMIT 1), NOW(), NOW()
FROM `tmp_rest_days` t JOIN `employees` e ON e.emp_code = t.emp_code;
DROP TEMPORARY TABLE `tmp_rest_days`;

